#!/bin/bash
# SC_example energy balance (WP8): for a pulse that is fully contained in the run (tests/data/sc_pulse.h5, generated by
# tests/tools/mkpulse.sh: A(t) = 0.5 sin^2(pi(t-0.6)/6) sin(pi(t-0.6)) for 0.6 < t < 6.6, h = 0.03, nt = 300)
#   energy_total(t) - energy_total(0) - energy_deposited(t) = 0
# up to the discretisation error (5e-7 here, O(h^6); E^j(end) = 0.171). Any other choice of the factors 1/2 or of the
# current's sign gives >= 1.5e-2. Tolerance 1e-5.
# usage: sc_energy_balance.sh SC_X H5FLAT WORKDIR INPUT PHI_H5
set -u
SC=$1; H5FLAT=$2; W=$3; IN=$4; PHI=$5
rm -rf "$W"; mkdir -p "$W"; cd "$W"
export OMP_NUM_THREADS=${OMP_NUM_THREADS:-2}
"$SC" "$IN" out.h5 "$PHI" > run.log 2>&1
rc=$?
if grep -q "Sanitizer" run.log; then echo "sanitizer report"; grep -A6 "ERROR: .*Sanitizer" run.log | head -20; exit 1; fi
[ $rc -eq 0 ] || { echo "SC.x failed with exit code $rc"; tail -5 run.log; exit 1; }
"$H5FLAT" dump out.h5 > dump.txt
# real parts of a complex 1x1 function dataset, t = 0..nt-1 (skip t = -1)
re() { awk -v ds="$1" '$1=="DATASET"{on=($2==ds); i=0; next} on{ if(i%2==0 && i>0) print $1; i++ }' dump.txt; }
re /energy_total/data > et.txt; re /energy_deposited/data > ej.txt
[ -s et.txt ] && [ -s ej.txt ] || { echo "energy datasets missing"; exit 1; }
paste et.txt ej.txt | awk 'NR==1{e0=$1} {r=$1-e0-$2; if(r<0)r=-r; if(r>m)m=r; ej=$2}
  END{printf "max|E_total(t)-E_total(0)-E^j(t)| = %.3e   E^j(end) = %.6f\n", m, ej;
      if(!(m < 1e-5)) {print "energy balance violated"; exit 1}
      if(!(ej > 0.1)) {print "deposited energy too small: pulse not seen"; exit 1}}'
